/* ----------------- Live Autocomplete Dropdown ----------------- */
.autocomplete-wrapper {
  position: relative;
  width: 100%;
}

/* Fix when autocomplete-wrapper is placed inside Bootstrap .input-group */
.input-group {
  flex-wrap: nowrap !important;
}

.input-group > .autocomplete-wrapper {
  position: relative;
  flex: 1 1 auto;
  width: 1%;
  min-width: 0;
  display: flex;
}

.input-group > .autocomplete-wrapper > .form-control {
  position: relative;
  flex: 1 1 auto;
  width: 100%;
  min-width: 0;
  height: 100%;
}

