.input-group > .autocomplete-wrapper:not(:first-child):not(:last-child) > .form-control {
  border-radius: 0 !important;
}

.input-group > .autocomplete-wrapper:not(:first-child):last-child > .form-control {
  border-top-left-radius: 0 !important;
